(window.CLAYSIMS_TEXT = window.CLAYSIMS_TEXT || {})["hu"] = {"launch":"Indítás","method":"Módszer","speed":"Korongsebesség","distance":"Távolság","demo":"Nézd meg a módszert","try":"Te jössz: nyomd meg, amikor lőnél","shoot":"Lövés","hit":"Találat! A korong eltörik.","behind":"Mögötte – a sörét a korong mögött ment el","ahead":"Előtte – a sörét a korong előtt ment el","perceived":"A döntéskor látott elétartás","actual":"Valós elétartás a lövés pillanatában","lab_note":"Lassítás, a tanításhoz egyszerűsített fizika. A sörét repülés közben lassul: átlagosan kb. 330 m/s 15 m-en, 300 m/s 25 m-en és 255 m/s 40 m-en (a csövet kb. 360–430 m/s sebességgel hagyja el). A döntéstől a lövésig kb. 0,15 s telik el (átlagos becslés). A gyűrű a sörétkép azon részét jelöli, amely elég sűrű a korong széttöréséhez: sugara kb. 33 cm 15 m-en és 45 cm 40 m-en. A csőtorkolat kb. 1 m-re van a szemtől. A korong röppályája menti távolságok, az elétartás és a gyűrű méretarányosak; a korong a valóságosnál nagyobbra van rajzolva, hogy látható legyen (nagyjából méretarányos ott, ahol az elétartást korongszélességben számoljuk). A valós elétartás a korong sebességétől, távolságától és szögétől, a tölténytől és a lövésztől függ.","unit_m":"m","unit_ft":"láb","unit_ms":"m/s","pair_report":"{term}: a 2. korong az 1. lövés hangjára indul","pair_sim":"{term}: mindkét korong egyszerre indul","pair_rafale":"{term}: a 2. korong ugyanabból a gépből, amint a gép újratöltött","listen":"Meghallgatás","no_shot":"Nem volt lövés.","at_muzzle":"a csőtorkolatnál nézve","compare":"Ugyanaz a korong, négy módszer: a valós elétartás ugyanaz, a látott nem","how_maintained":"A csövek a korong előtt várnak, a korong közeledik hozzájuk. Nyomd meg a „Lövés” gombot, amikor a távolság jónak látszik: ekkor a puska a korong sebességével halad, és tartja ezt az elétartást.","how_swing":"A csövek a korong mögül indulnak, és gyorsabbak nála. Nyomd meg a „Lövés” gombot, amikor a csövek elhagyják a korong elejét: a késleltetés alatt a puska tovább előz, ezért a valós elétartás nagyobb.","how_pullaway":"A csövek előbb a koronggal együtt mennek, aztán előre gyorsulnak. Nyomd meg a „Lövés” gombot, amíg a puska még gyorsul: a látott elétartás kisebb a valósnál.","how_ambush":"A csövek mozdulatlanul várnak egy ponton a korong előtt. Nyomd meg a „Lövés” gombot, mielőtt a korong odaér: a sörétnek idő kell, így ha akkor lősz, amikor a korong már ott van, a lövés mögé megy.","stop_gun":"A puska megállítása lövéskor (hiba)","clay_widths":"korongszélesség","unit_cm":"cm","unit_in":"hüvelyk","anim_play":"Lejátszás","anim_replay":"Újra","anim_slow":"Lassítás","anim_marker":"animációval","anim_h_flight":"Nézd meg, hogyan repül a korong","anim_h_points":"Nézd meg a három pontot","anim_h_eyes":"Nézd meg, hová néz a szem","anim_h_stance":"Nézd meg a beállást","anim_h_pair":"Nézd meg, hogyan indul egy dublé","anim_h_lead":"Nézd meg, hogyan működik az elétartás","anim_h_mount":"Nézd meg a vállba vételt","anim_h_follow":"Nézd meg az elkísérést","anim_h_call":"Nézd meg a korong kérését és indítását","anim_h_gunpos":"Nézd meg a fegyver helyzetét","anim_h_misfire":"Nézd meg, mi a teendő, ha a lövés elmarad","anim_w_flight":"Kövesd az egész röppályát: honnan jön a korong, hol látod jól, és merre megy.","anim_w_points":"A szem a korongfelvételi ponton vár, a csövek a fegyvertartási ponton; a korong a lövési ponton törik.","anim_w_eyes":"Laza fókusz a korongfelvételi pont körül, aztán éles fókusz a korong elülső szélén.","anim_w_stance":"Az elülső láb a lövési pontra mutat; a test visszafordul a fegyvertartási pontig.","anim_w_pair":"Figyeld, mikor indul a második korong: a lövés után, az elsővel együtt vagy ugyanabból a gépből.","anim_w_lead":"Figyeld a csövek és a korong közti távolságot a lövés pillanatában, aztán próbáld ki te is.","anim_w_mount":"Először a csövek indulnak a koronggal; a vállba vétel a lövéssel együtt fejeződik be.","anim_w_follow":"A fegyver a lövés után is mozog; ha lövéskor megállítod, a sörét mögé megy.","anim_w_call":"Az óra mutatja, mikor indul a korong a kérés vagy a bíró jele után; a késve induló korong „No bird”.","anim_w_gunpos":"A Sporting™-ban a tus a mellényen lévő jelölővonal alatt marad, amíg a korong meg nem jelenik.","anim_w_misfire":"Ha a lövés elmarad, maradj a helyeden: a fegyver zárva, a lőtér felé mutat, amíg a bíró meg nem vizsgálja.","anim_unit_s":"mp","anim_after_call":"a kérés után","anim_after_signal":"a jel után","anim_t_signal":"Sporting™: a bíró jele","anim_t_late":"Késve induló korong","anim_t_manual":"Compak® Sporting: kézzel","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Fegyver már vállban a kéréskor","anim_s_in_time":"A korong a jel után {n} mp múlva indul: időben (a határ {max} mp).","anim_s_late":"A korong a jel után {n} mp múlva indul, később, mint {max} mp: a bíró bemondja, hogy „No bird”, és a korongot újra dobják.","anim_s_manual":"Kézi indítás: a korong a kérés után {n} mp múlva indul (megengedett: 0–{max} mp).","anim_s_sonopull":"Hangvezérlés: a mikrofon meghallja a kérést, és a korong mindig {n} mp múlva indul.","anim_s_gun_low":"Készenléti testhelyzet: a tus a mellényen lévő vonal alatt érinti a testet.","anim_s_gun_mount":"Megjelent a korong: csak most kerül a fegyver a vállba.","anim_s_early":"Kérés már vállba vett fegyverrel: első alkalommal szóbeli figyelmeztetés és sárga lap.","anim_s_click":"Kattanás: a fegyver nem sült el.","anim_s_hold":"Maradj a helyeden: a fegyver zárva, a lőtér felé mutat; ne nyisd ki, és ne nyúlj a biztosítóhoz.","anim_s_ref":"A bíró megvizsgálja a fegyvert.","anim_s_repeat":"A kör első hibája: a korongot újra dobják.","anim_stop":"Leállítás","anim_s_mount_ready":"Készen: a fegyver lent van, a szem a korongra vár.","anim_s_move":"Mozdulat: az elülső kéz a korong vonalán indítja a csöveket.","anim_s_mount":"Vállba vétel: a tus az archoz és a vállba kerül; a fej mozdulatlan marad.","anim_s_shoot":"Lövés: a vállba vétel a lövéssel együtt fejeződik be.","anim_scale":"Csak a lövész és a lőállás méretarányos; a lőtér és a korong röppályája rövidítve látható.","anim_h_pattern":"Watch how the choke changes the pattern","anim_w_pattern":"A shot at a plate from 36.6 m (40 yards). Pick a choke: the tighter it is, the more shot lands in the 76 cm circle and the denser it is on the target in the centre.","anim_pattern_in":"In the 76 cm circle: ≈ {n}% of the shot","anim_pattern_load":"Simplified. 28 g of No. 7½ shot is about 370 pellets; the percentages are a guide for lead shot, and your gun and cartridge may give different ones. The target (110 mm) and the circle are to scale.","anim_h_miss":"Watch where the shot went","anim_w_miss":"What a coach standing behind the shooter sees: first where the shot went compared with the clay, then why. Switch the tabs.","anim_miss_behind":"Behind: the shot passed behind the target — not enough lead, or the gun slowed down or stopped. Very common on crossers.","anim_miss_front":"In front: too much lead, often after over-correcting. Many coaches like this miss: it shows the gun kept moving.","anim_miss_over":"Over: common on dropping targets, rabbits and incomers, and often linked to the head coming off the stock.","anim_miss_under":"Under: typical on rising targets that are still climbing at the shot.","anim_h_ties":"Watch how ties are broken","anim_w_ties":"Places 1–3: a shoot-off; below third: countback (in Compak® Sporting the same, from the 8th Compak to the 1st). The numbers are an example: 200 targets, 8 layouts of 25.","anim_ties_shooter":"Shooter","anim_ties_total":"Total","anim_ties_place":"Place","anim_ties_layout":"Layout","anim_ties_so":"Shoot-off (25)","anim_ties_sd":"Sudden death","anim_ties_cb0":"D and E both have 181 of 200: 5th place. Below third there is no shoot-off — countback decides the order on the score sheet.","anim_ties_cb_eq":"Layout {n}: {a} : {b} — level, look at the one before.","anim_ties_cb_win":"Layout {n}: {a} : {b} — {who} is listed higher. Both keep the same place: 5=.","anim_ties_so0":"A and B both have 192 of 200 — a tie for 1st place. A shoot-off decides it: a round of 25 targets.","anim_ties_so1":"Shoot-off: {a} : {b} — still level. Now sudden death: the first to miss is out.","anim_ties_sd_ok":"Target {n}: both hit.","anim_ties_sd_both":"Target {n}: both missed. They have shot the same number of targets, so nobody is out.","anim_ties_sd_out":"Target {n}: A hit, B missed — B is out. A takes 1st place.","anim_h_stock":"See how a stock is measured","anim_w_stock":"A coach or a gun fitter sets the stock dimensions; the numbers here are only a guide.","anim_stock_b_fit":"Fits","anim_stock_b_short":"Too short","anim_stock_b_long":"Too long","anim_stock_b_off":"Cast off","anim_stock_b_on":"Cast on","anim_stock_fit":"Length of pull is measured from the trigger to the middle of the butt pad. For adults it is often about 36–38 cm (14¼–15 in); many factory competition guns come at about 37.5 cm (14¾ in). This is only a guide.","anim_stock_short":"Too short: under recoil the thumb of the trigger hand may hit your nose, and recoil feels stronger.","anim_stock_long":"Too long: the stock catches on your clothes as you mount the gun and may land on the arm instead of the shoulder.","anim_stock_off":"Cast off: the stock bends slightly to the right, for a right-handed shooter, so that the eye sits exactly over the rib. It is a matter of a few millimetres; the drawing exaggerates it.","anim_stock_on":"Cast on: the stock bends to the left, for a left-handed shooter. Without the cast a shooter needs, a gun may keep shooting to one side.","anim_cheek":"arc a pofadékon","anim_l_foot":"elülső láb","anim_l_body":"test","anim_h_hit":"Nézze meg, mi történik a koronggal","anim_w_hit":"A nagyító a lövéstől követi a korongot: csak por, vagy leváló darab.","anim_t_hit_dust":"Csak por","anim_t_hit_chip":"Látható darab","anim_hit_dust":"A lövéskép széle súrolja a korongot: por száll fel, de egy darab sem válik le — a korong egészben repül tovább.","anim_hit_chip":"A lövéskép széle súrolja a korongot: egy kicsi, de jól látható darab leválik; a korong többi része tovább repül.","anim_t_late_manual":"Compak® Sporting: késői korong (kézi indítás)","anim_s_manual_late":"Kézi indítás: a korong {n} mp-cel a vezényszó után repül ki, később mint {max} mp: a bíró „No Bird”-öt hirdet.","anim_t_uncalled":"Korong vezényszó nélkül","anim_t_uncalled_shot":"Korong vezényszó nélkül: lövés","anim_s_uncalled":"A lövő még nem adott vezényszót, de a korong már kirepült. Nem lő.","anim_s_uncalled_shot":"A korong vezényszó nélkül repül ki. A lövő későn emeli vállhoz a fegyvert, lő — és hibáz.","anim_t_broken":"Indításkor törött","anim_s_broken":"A korong már kettétörve hagyja el a dobógépet.","anim_s_broken_hit":"A lövő a nagyobb darabot találja el.","anim_t_nobird_shot":"Lövés „No Bird” után","anim_s_nobird_shot":"A bíró „No Bird”-öt hirdet, de a lövő mégis lő.","anim_t_noise_shot":"Zaj a lövésnél","anim_s_noise_shot":"Közvetlenül a lőállás mögött hangosan megszólal egy telefon; a lövő összerezzen és hibáz.","anim_t_noise_call":"Zaj a vezényszónál","anim_s_noise_call":"Épp a vezényszónál hangosan szól egy hangosbemondó; a lövő összerezzen és leengedi a fegyvert.","anim_t_neighbour":"Korong a szomszédos Compakról","anim_s_neighbour":"Miközben a lövő követi a korongot, a szomszédos Compak egyik korongja átrepül a látóterén. A sajátját elhibázza.","anim_t_gust":"Széllökés","anim_s_gust":"Egy széllökés épp a lövés pillanatában lenyomja a korongot; a lövés fölötte megy el."};
